236px;font-size:11px;font-weight:800;letter-spacing:1.5px;cursor:pointer;box-shadow:0 9px 36px #a5252d40;transition:transform .2s,background .2s}.primary-button:hover{background:#f0565b;transform:translateY(-2px)}.primary-button span{font-size:17px;margin-left:20px}.title-foot{display:flex;gap:11px;align-items:center;margin-top:47px;font-size:9px;letter-spacing:1.7px;color:#aaa5a4}.title-foot span:nth-child(even){color:var(--red)}.title-mark{position:absolute;right:13%;top:16%;font-size:min(40vw,480px);font-family:serif;color:#ffffff08;line-height:1;user-select:none;text-shadow:0 0 80px #ee36461b}.title-controls{position:absolute;bottom:25px;left:8.2%;font-size:9px;letter-spacing:1.2px;color:#a8a2a3}kbd{font:700 9px 'DM Sans';letter-spacing:.5px;padding:5px 7px;border:1px solid #ffffff3d;background:#ffffff0b;border-radius:3px;color:#eee}.title-controls i{padding:0 7px;color:var(--red)}.hud{position:absolute;inset:0;z-index:3;pointer-events:none;transition:opacity .4s}.hidden{opacity:0!important;visibility:hidden!important}.topbar{position:absolute;top:0;left:0;right:0;height:77px;display:flex;align-items:center;padding:0 34px;background:linear-gradient(180deg,#0b0c13d9,transparent);pointer-events:auto}.brand{display:flex;align-items:center;gap:10px;font-size:10px;line-height:1.02;letter-spacing:1.4px;font-weight:500}.brand b{font-weight:800}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:1px solid #e5484d77;color:var(--red);font-family:serif;font-size:23px}.chapter{margin-left:40px;padding-left:21px;border-left:1px solid var(--line);display:flex;flex-direction:column;gap:3px}.chapter-label{font-size:8px;letter-spacing:1.7px;color:#aaa}.chapter-label b{color:var(--red);padding-left:4px}.chapter strong{font-size:18px;letter-spacing:.8px;font-weight:700}.icon-button{margin-left:auto;background:#11131ab3;border:1px solid #ffffff36;width:36px;height:36px;font-size:16px;cursor:pointer;pointer-events:auto}.left-panel{position:absolute;left:34px;top:99px;width:272px;background:linear-gradient(135deg,#13141de8,#111119c9);border:1px solid var(--line);padding:14px 15px 13px;box-shadow:0 12px 35px #0003}.character-card{display:flex;align-items:center;gap:11px}.char-avatar{height:44px;width:44px;display:grid;place-items:center;background:linear-gradient(135deg,#562d37,#1a1721);border:1px solid #ed5c5966;color:#f5d6c6;font-family:serif;font-size:26px}.char-info{display:flex;flex-direction:column;gap:3px;min-width:0}.char-info span,.char-info small{font-size:8px;letter-spacing:1.2px;color:#aaa}.char-info strong{font-family:'Barlow Condensed';font-weight:700;font-size:17px;letter-spacing:.4px}.char-info small{color:#e78679;font-size:8px}.switch-hint{margin-left:auto;border:1px solid #ffffff30;color:#aaa;padding:4px 6px;font-size:9px}.bars{margin-top:16px}.bar-label{display:flex;justify-content:space-between;font-size:8px;letter-spacing:1.1px;color:#b9b3b0;margin-bottom:6px}.bar-label b{font-size:9px;color:#eee;letter-spacing:.4px}.bar-track{width:100%;height:5px;background:#ffffff1a;overflow:hidden}.bar-track i{height:100%;width:100%;display:block;background:linear-gradient(90deg,#bd333a,#fa6457);transition:width .25s}.energy-label{margin-top:11px}.energy-track i{background:linear-gradient(90deg,#4258ab,#65a6ff)}.objective{display:flex;align-items:center;gap:11px;margin-top:15px;padding-top:12px;border-top:1px solid var(--line)}.objective-icon{font-size:18px;color:var(--gold)}.objective div{display:flex;flex-direction:column;gap:3px}.objective small{font-size:7px;letter-spacing:1.3px;color:#aaa}.objective strong{font-size:10px;font-weight:600}.right-panel{position:absolute;right:34px;top:104px;text-align:right}.area-label{display:flex;align-items:center;justify-content:flex-end;gap:8px;font-size:9px;letter-spacing:1.6px;font-weight:700}.pulse-dot{width:6px;height:6px;border-radius:50%;background:#df5559;box-shadow:0 0 10px #e5484d;animation:pulse 1.8s infinite}.threat-level{margin-top:8px;font-size:8px;letter-spacing:1px;color:#aaa}.threat-level b{color:var(--gold);margin-left:5px}.bottom-hud{position:absolute;bottom:20px;left:34px;right:34px;display:flex;align-items:flex-end;justify-content:space-between}.controls-hint{display:flex;gap:10px;color:#aaa;font-size:8px;letter-spacing:.8px}.controls-hint span{display:flex;align-items:center;gap:5px}.controls-hint kbd{font-size:8px;padding:4px 5px}.skill-row{display:flex;gap:7px}.skill-chip{background:#12131bc9;border:1px solid #ffffff30;min-width:104px;padding:7px 9px;display:flex;flex-direction:column;gap:5px}.skill-chip b{font-size:8px;color:var(--gold)}.skill-chip span{font-size:8px;letter-spacing:.6px}.toast{position:absolute;top:22%;left:50%;transform:translate(-50%,-12px);opacity:0;padding:10px 18px;background:#14141ce8;border:1px solid #e4bd7645;color:#f4e3bf;font-family:'Barlow Condensed';font-size:17px;letter-spacing:1.2px;transition:all .3s}.toast.show{opacity:1;transform:translate(-50%,0)}.dialogue{pointer-events:auto;position:absolute;left:50%;bottom:100px;transform:translateX(-50%);width:min(590px,88vw);padding:19px 24px 17px;background:linear-gradient(110deg,#13131bf2,#111119eb);border:1px solid #ffffff2e;border-left:3px solid var(--red);box-shadow:0 15px 50px #0008}.dialogue-name{font-family:'Barlow Condensed';font-size:17px;letter-spacing:1.1px;color:#f16a69;font-weight:700}.dialogue p{font-size:13px;line-height:1.7;color:#e3ddda;margin:6px 0 12px}.dialogue button{border:0;background:none;color:#d7c8b3;padding:0;font-size:9px;font-weight:700;letter-spacing:1.4px;cursor:pointer}.dialogue button span{color:var(--red);margin-left:7px}.mission-banner{position:absolute;top:26%;left:50%;transform:translate(-50%,-12px);opacity:0;display:flex;flex-direction:column;gap:6px;text-align:center;transition:all .5s;text-shadow:0 2px 10px #000}.mission-banner.show{opacity:1;transform:translate(-50%,0)}.mission-banner span{font-size:8px;letter-spacing:3px;color:var(--gold)}.mission-banner b{font-family:'Barlow Condensed';font-size:31px;letter-spacing:1.5px}.interact-prompt{position:absolute;left:50%;top:50%;transform:translate(-50%,55px);display:flex;align-items:center;gap:8px;padding:7px 11px;background:#101018cc;border:1px solid #ffffff37;font-size:9px;letter-spacing:1px}.overlay-screen{background:#08090bc7;backdrop-filter:blur(7px)}.pause-box{text-align:center;padding:48px;min-width:min(500px,90vw);border:1px solid #ffffff29;background:linear-gradient(140deg,#17171fee,#0d0e14f5);box-shadow:0 30px 90px #0007}.pause-box .eyebrow{justify-content:center;color:var(--gold)}.pause-box h2{font-size:56px;line-height:1;margin:18px 0 8px;letter-spacing:.6px}.pause-box p{color:#aaa;font-size:13px;margin:0 0 25px}.pause-note{margin-top:24px;color:#999;font-size:10px}.loading{position:absolute;z-index:9;inset:0;background:#101017;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;color:#c4bcb8;font-size:9px;letter-spacing:3px;transition:opacity .7s}.loading.done{opacity:0;visibility:hidden}.loading-seal{font-family:serif;color:var(--red);font-size:52px;animation:rotate 8s linear infinite}.loading i{width:110px;height:1px;background:linear-gradient(90deg,transparent,var(--red),transparent)}.touch-controls{display:none;pointer-events:auto}.joystick{position:absolute;left:20px;bottom:34px;width:108px;height:108px;border-radius:50%;border:1px solid #ffffff44;background:#11131a70;touch-action:none}.stick{position:absolute;width:43px;height:43px;border-radius:50%;left:32px;top:32px;background:#ffffff2e;border:1px solid #ffffff70}.touch-actions{position:absolute;right:20px;bottom:28px;display:flex;gap:9px;align-items:flex-end}.touch-actions button{width:56px;height:56px;border-radius:50%;border:1px solid #ffffff66;background:#15151dcc;font-size:9px;font-weight:700;letter-spacing:.5px;touch-action:none}.touch-actions button:first-child{width:68px;height:68px;background:#792b34d9;border-color:#ee667180}.touch-actions button:active{background:#e5484d}.touch-visible .touch-controls{display:block}@keyframes pulse{50%{opacity:.42;box-shadow:0 0 3px #e5484d}}@keyframes rotate{to{transform:rotate(360deg)}}
@media(max-width:700px){.title-content{left:8%;top:19%}h1{font-size:clamp(70px,17vw,116px);margin:23px 0}.title-copy{font-size:13px}.title-foot{margin-top:30px;font-size:7px;gap:7px}.title-controls{left:8%;font-size:7px}.topbar{height:65px;padding:0 17px}.brand{font-size:8px}.brand-mark{width:29px;height:29px;font-size:19px}.chapter{margin-left:16px;padding-left:12px}.chapter strong{font-size:14px}.chapter-label{font-size:7px}.icon-button{width:32px;height:32px}.left-panel{top:77px;left:12px;width:220px;padding:10px}.character-card{gap:8px}.char-avatar{width:36px;height:36px;font-size:21px}.char-info strong{font-size:14px}.char-info span,.char-info small{font-size:7px}.bars{margin-top:11px}.objective{margin-top:10px;padding-top:8px}.right-panel{right:13px;top:82px}.area-label{font-size:7px}.threat-level{font-size:7px}.bottom-hud{left:12px;right:12px;bottom:11px}.controls-hint{display:none}.skill-row{display:none}.touch-visible .bottom-hud{bottom:152px}.dialogue{bottom:144px;width:calc(100% - 28px);padding:14px 16px}.dialogue p{font-size:12px;margin:5px 0 9px}.mission-banner{top:32%}.mission-banner b{font-size:25px}.pause-box{padding:35px 20px}.pause-box h2{font-size:42px}.pause-note{line-height:1.6}.interact-prompt{top:49%}}
@media(max-height:650px) and (min-width:701px){.left-panel{top:82px}.topbar{height:65px}.bottom-hud{bottom:12px}.dialogue{bottom:72px}.title-content{top:15%}h1{font-size:100px;margin:19px 0}.title-foot{margin-top:26px}}

import * as THREE from 'three';

const canvas = document.querySelector('#world');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: false });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.8));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x121723);
scene.fog = new THREE.FogExp2(0x141923, 0.012);
const camera = new THREE.PerspectiveCamera(54, innerWidth / innerHeight, 0.1, 280);
const clock = new THREE.Clock();
const world = new THREE.Group(); scene.add(world);
const ambient = new THREE.HemisphereLight(0x9caec9, 0x24212a, 1.55); scene.add(ambient);
const moon = new THREE.DirectionalLight(0xc8d7ff, 2.45); moon.position.set(-25, 34, -9); moon.castShadow = true;
moon.shadow.mapSize.set(1024, 1024); moon.shadow.camera.left = -48; moon.shadow.camera.right = 48; moon.shadow.camera.top = 48; moon.shadow.camera.bottom = -48; scene.add(moon);
const redLight = new THREE.PointLight(0xe44c50, 38, 35, 2); redLight.position.set(0, 5, 37); world.add(redLight);
const goldLight = new THREE.PointLight(0xe5a95e, 22, 30, 2); goldLight.position.set(0, 3, 54); world.add(goldLight);
const mats = {};
const mat = (name, color, roughness = .86, extra = {}) => mats[name] ||= new THREE.MeshStandardMaterial({ color, roughness, ...extra });
const boxGeo = new THREE.BoxGeometry(1,1,1);
function box(parent, name, pos, size, material, cast = true) { const m = new THREE.Mesh(boxGeo, material); m.name=name; m.position.set(...pos); m.scale.set(...size); m.castShadow=cast; m.receiveShadow=true; parent.add(m); return m; }
function sphere(parent, pos, scale, material, seg=12) { const m = new THREE.Mesh(new THREE.SphereGeometry(1,seg,Math.max(8,seg-2)),material); m.position.set(...pos); m.scale.set(...scale); m.castShadow=true; m.receiveShadow=true; parent.add(m); return m; }
function cylinder(parent, pos, radiusTop, radiusBottom, height, material, seg=8) { const m = new THREE.Mesh(new THREE.CylinderGeometry(radiusTop,radiusBottom,height,seg),material); m.position.set(...pos); m.castShadow=true; m.receiveShadow=true; parent.add(m); return m; }
function plane(parent, pos, size, material) { const m = new THREE.Mesh(new THREE.PlaneGeometry(...size),material); m.rotation.x=-Math.PI/2; m.position.set(...pos); m.receiveShadow=true; parent.add(m); return m; }

// Campus grounds and the path through the veil.
plane(world,[0,-.12,12],[220,220],mat('earth',0x252731));
plane(world,[0,-.07,15],[9,125],mat('path',0x34333a));
for(let i=0;i<38;i++){
  const z=-45+i*3.2;
  box(world,'path-stone',[Math.sin(i*8)*.55,-.015,z],[2.2,.045,2.1],mat('stone'+i, i%3===0?0x49474b:0x3e3d43),false);
  if(i%2===0){const x=(i%4?1:-1)*(5.5+Math.sin(i*4)*2); const s=.6+(i%5)*.24;
    cylinder(world,[x,.9,z+Math.cos(i)*2],.2*s,.5*s,1.8*s,mat('trunk'+i,0x292a30),6);
    const crown=sphere(world,[x,2.5*s,z+Math.cos(i)*2],[1.3*s,2.3*s,1.3*s],mat('canopy'+i,i%3===0?0x263839:0x202d32),8); crown.castShadow=true;
    sphere(world,[x-.45*s,2.2*s,z+1],[.5*s,1.05*s,.55*s],mat('canopyb'+i,0x263538),8);
  }
}
// Mossy boundary walls, lanterns and torii gate.
for(const side of [-1,1]){
  for(let i=0;i<8;i++){
    const z=-27+i*13;
    box(world,'wall',[side*12,1.2,z],[.55,2.4,12.9],mat('wall'+side+i,0x33323a));
    box(world,'wallcap',[side*12,2.45,z],[.85,.22,13],mat('wallcap'+side+i,0x48434a));
    if(i%2===0){const x=side*8.2; cylinder(world,[x,1.15,z+4],.08,.12,2.3,mat('lampstand'+i,0x353038),8);box(world,'lantern',[x,2.25,z+4],[.65,.8,.65],mat('lantern'+side+i,0xe6a45e,.4,{emissive:0xc4522a,emissiveIntensity:1.6}));}
  }
}
// Training hall — a timber dojo tucked into the trees.
const dojo= new THREE.Group(); dojo.position.set(0,0,45); world.add(dojo);
box(dojo,'dojo-base',[0,.15,0],[17,.5,12],mat('base',0x38333a));
box(dojo,'dojo-floor',[0,.45,0],[16,.18,11],mat('woodfloor',0x60473e));
box(dojo,'dojo-back',[0,3.2,5.25],[16,5.5,.55],mat('darkwood',0x3c2b2d));
box(dojo,'dojo-sideL',[-7.6,3.1,0],[.5,5.3,10],mat('woodL',0x493234)); box(dojo,'dojo-sideR',[7.6,3.1,0],[.5,5.3,10],mat('woodR',0x493234));
box(dojo,'dojo-front',[0,5.7,0],[18,.45,12],mat('roof',0x24242e));
for(const x of [-7,7]){box(dojo,'pillar',[x,2.9,-4.8],[.48,5.7,.48],mat('pillar'+x,0x6a4240));box(dojo,'pillar-foot',[x,.25,-4.8],[.8,.5,.8],mat('foot'+x,0x39343c));}
for(let i=-5;i<=5;i+=2.5)box(dojo,'rafter',[i,5.98,-.3],[.22,.25,12.2],mat('rafter'+i,0x403237));
box(dojo,'dojo-sign',[0,3.3,-5.58],[3.3,1.4,.18],mat('sign',0x211d25));
const signKanji = new THREE.Mesh(new THREE.PlaneGeometry(1.35,1.05),new THREE.MeshBasicMaterial({color:0xe9d8bd}));signKanji.position.set(0,3.35,-5.46);dojo.add(signKanji);
// Vermilion gate marks the threshold.
const gate=new THREE.Group(); gate.position.set(0,0,23);world.add(gate);
const redWood=mat('redwood',0x8e3039);
for(const x of [-4.3,4.3]){box(gate,'gate-post',[x,3,0],[.62,6,.68],redWood);box(gate,'gate-foot',[x,.35,0],[1,.7,1],mat('gatefoot',0x39333a));}
box(gate,'gate-beam',[0,5.85,0],[11,.7,1],redWood);box(gate,'gate-cap',[0,6.35,0],[12,.28,1.5],mat('gatecap',0x28252c));box(gate,'gate-cross',[0,4.8,.05],[8,.3,.75],redWood);
// Ritual seal and surrounding candles.
const seal = new THREE.Group();seal.position.set(0,.02,59);world.add(seal);
const sealMat=new THREE.MeshBasicMaterial({color:0xd54d54,transparent:true,opacity:.8,side:THREE.DoubleSide});
const ring=new THREE.Mesh(new THREE.RingGeometry(3.2,3.35,64),sealMat);ring.rotation.x=-Math.PI/2;seal.add(ring);
const ring2=new THREE.Mesh(new THREE.RingGeometry(2.1,2.18,64),new THREE.MeshBasicMaterial({color:0xe49d68,transparent:true,opacity:.7,side:THREE.DoubleSide}));ring2.rotation.x=-Math.PI/2;seal.add(ring2);
for(let i=0;i<8;i++){const a=i*Math.PI/4;const x=Math.cos(a)*3.9,z=Math.sin(a)*3.9;cylinder(world,[x,.35,59+z],.1,.13,.7,mat('candle'+i,0x49393b));sphere(world,[x,.78,59+z],[.1,.2,.1],mat('flame'+i,0xffa364,.3,{emissive:0xff6935,emissiveIntensity:2}));}
// Distant silhouette city and moon.
sphere(scene,[-35,44,70],[7,7,7],new THREE.MeshBasicMaterial({color:0xd6d9e8}),24);
for(let i=0;i<28;i++){const x=-85+i*6.4;const h=5+(Math.sin(i*9)+1)*8;box(world,'city',[x,h/2,104],[4,h,4],mat('building'+i,0x1b202b),false);for(let y=1;y<h;y+=2)box(world,'window',[x+(i%2?.4:-.4),y,101.95],[.22,.45,.04],mat('window'+i+y,0x706b65,.5,{emissive:0x514b44,emissiveIntensity:.3}),false);}

const roster=[
 {name:'YUJI ITADORI',kanji:'悠',style:'DIVERGENT FIST',attack:'BLACK FLASH',skill:'CURSED BURST',coat:0x332c38,shirt:0xc54850,hair:0xa94a4b,accent:0xe55c5c},
 {name:'NOBARA KUGISAKI',kanji:'釘',style:'STRAW DOLL TECHNIQUE',attack:'HAMMER STRIKE',skill:'RESONANCE',coat:0x352d2b,shirt:0x9e542d,hair:0xb26b3c,accent:0xe5a454},
 {name:'MEGUMI FUSHIGURO',kanji:'恵',style:'TEN SHADOWS',attack:'SHADOW SLASH',skill:'DIVINE DOG',coat:0x252b37,shirt:0x2d394e,hair:0x202531,accent:0x7290d4}
];
function makeSorcerer(index=0){
 const group=new THREE.Group(), rig=new THREE.Group();group.add(rig);group.userData.rig=rig;group.userData.parts=[];
 const c=roster[index], skin=mat('skin'+index,0xe4b69e), hair=mat('hair'+index,c.hair), coat=mat('coat'+index,c.coat), shirt=mat('shirt'+index,c.shirt), boots=mat('boots'+index,0x201e26), glow=mat('glow'+index,c.accent,.35,{emissive:c.accent,emissiveIntensity:.45});
 sphere(rig,[0,1.58,0],[.35,.38,.31],skin);
 sphere(rig,[0,1.91,-.02],[.39,.24,.35],hair);
 for(let s of [-1,1])sphere(rig,[s*.3,1.86,.02],[.19,.24,.24],hair,10);
 // Face marks and eyes face forward along +Z.
 box(rig,'eyeL',[-.12,1.6,.295],[.07,.035,.025],mat('eye'+index,0x29242a),false);box(rig,'eyeR',[.12,1.6,.295],[.07,.035,.025],mat('eyeR'+index,0x29242a),false);
 box(rig,'torso',[0,1.03,0],[.75,.78,.42],coat);
 box(rig,'collar',[0,1.39,.04],[.58,.22,.46],shirt);
 box(rig,'belt',[0,.68,.01],[.7,.12,.43],mat('belt'+index,0x171820));
 const arms=[],legs=[];
 for(const s of [-1,1]){
   const arm=new THREE.Group();arm.position.set(s*.48,1.28,0);rig.add(arm);box(arm,'sleeve',[s*.12,-.22,0],[.28,.6,.31],coat);sphere(arm,[s*.15,-.51,.02],[.13,.14,.13],skin,10);arms.push(arm);
